// Parity test: the JS port must reproduce the original Python results on the
// same snapshot of data. Requires fixtures generated by tests/fixtures (see README);
// skipped automatically when the snapshot is not present.
import test from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import { compactHistory } from "../public/assets/js/lib/compact.js";
import { PriceSeries, pointRpi, lastMonthYoY, monthlyHistory, singleItem } from "../public/assets/js/lib/rpi.js";
import { toDay, fromDay } from "../public/assets/js/lib/dates.js";

const DIR = process.env.PARITY_DIR;
// The original Python app's 99-item basket, with no outlier guard.
const DEFAULT_BASKET = JSON.parse(fs.readFileSync(new URL("./fixtures/legacy-basket.json", import.meta.url), "utf8"));
const RAW = { maxRatio: Infinity };

// The Python app filled data gaps with bfill() before ffill(), i.e. with the
// NEXT known price (a look-ahead bug). The port deliberately forward-fills
// instead. To prove the rest of the maths is identical, the parity test
// re-applies Python's back-fill to the compact series before comparing.
function emulatePythonBackfill(c, points) {
  const DAY = 86_400_000;
  const have = new Set(points.filter((p) => p.price > 0).map((p) => Math.floor(p.timestamp / DAY)));
  let next = null;
  for (let i = c.prices.length - 1; i >= 0; i--) {
    if (have.has(c.start + i)) next = c.prices[i];
    else c.prices[i] = next;
  }
}
const enabled = DIR && fs.existsSync(`${DIR}/python.json`);

test("JS port matches original Python calculator", { skip: !enabled && "set PARITY_DIR to run" }, () => {
  const ref = JSON.parse(fs.readFileSync(`${DIR}/python.json`, "utf8"));
  const mapping = JSON.parse(fs.readFileSync(`${DIR}/mapping.json`, "utf8"));
  const idByName = new Map(mapping.map((i) => [i.name.toLowerCase(), i.id]));
  const cache = new Map();
  const get = (name) => {
    const id = idByName.get(name.toLowerCase());
    if (!cache.has(id)) {
      const raw = JSON.parse(fs.readFileSync(`${DIR}/hist/${id}.json`, "utf8"));
      const c = compactHistory(raw[String(id)]);
      if (c) emulatePythonBackfill(c, raw[String(id)]);
      cache.set(id, c ? new PriceSeries(c) : null);
    }
    return cache.get(id);
  };
  const today = toDay("2026-10-11");
  const close = (a, b, tol, label) => assert.ok(Math.abs(a - b) < tol, `${label}: js=${a} py=${b}`);

  close(pointRpi(DEFAULT_BASKET, get, toDay("2025-10-04"), toDay("2026-10-04")).value, ref.yoy7, 0.02, "yoy7");
  close(pointRpi(DEFAULT_BASKET, get, toDay("2025-09-11"), toDay("2026-09-11"), RAW).value, ref.yoy30, 0.02, "yoy30");
  close(pointRpi(DEFAULT_BASKET, get, today - 7, today, RAW).value, ref.wow, 0.02, "wow");
  close(lastMonthYoY(DEFAULT_BASKET, get, today, RAW).value, ref.lastMonth, 0.02, "lastMonth");

  const hist = monthlyHistory(DEFAULT_BASKET, get, today, 240, RAW);
  assert.equal(hist.length, ref.history.length, "history length");
  hist.forEach((h, i) => {
    assert.equal(fromDay(h.month), ref.history[i][0]);
    close(h.value, ref.history[i][1], 0.02, `history ${ref.history[i][0]}`);
  });

  const shark = singleItem(get("Shark"), toDay("2025-10-11"), today);
  close(shark.change, ref.shark[2], 0.01, "shark");
});
